From 8bdfc61e0e8d4fda3894c67261c3da4b11c3703b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:42:21 +0100
Subject: [PATCH] layershellv1window: move resized surfaces with their new size

A layer surface that changed size was moved to its new position at once
while still showing its old size, so a centred panel jumped off centre.
Move it only when the client commits a buffer with the new size instead.

BUG: 518384
---
 src/layershellv1window.cpp | 21 ++++++++++++---------
 src/layershellv1window.h   |  2 ++
 2 files changed, 14 insertions(+), 9 deletions(-)

diff --git a/src/layershellv1window.cpp b/src/layershellv1window.cpp
index bee106ff1b..51fa64e39c 100644
--- a/src/layershellv1window.cpp
+++ b/src/layershellv1window.cpp
@@ -233,24 +233,22 @@ void LayerShellV1Window::moveResizeInternal(const RectF &rect, MoveResizeMode mo
 {
     const QSizeF requestedClientSize = surface()->snappedSize(nextFrameSizeToClientSize(rect.size()));

+    // The surface is moved once the client commits a buffer with the new size.
     if (!m_configureEvents.isEmpty()) {
-        const LayerShellV1ConfigureEvent &lastLayerShellV1ConfigureEvent = m_configureEvents.constLast();
+        LayerShellV1ConfigureEvent &lastLayerShellV1ConfigureEvent = m_configureEvents.last();
         if (lastLayerShellV1ConfigureEvent.size != requestedClientSize) {
             const quint32 serial = m_shellSurface->sendConfigure(requestedClientSize);
-            m_configureEvents.append({serial, requestedClientSize});
+            m_configureEvents.append({serial, requestedClientSize, rect.topLeft()});
+        } else {
+            lastLayerShellV1ConfigureEvent.position = rect.topLeft();
         }
     } else if (requestedClientSize != clientSize()) {
         const quint32 serial = m_shellSurface->sendConfigure(requestedClientSize);
-        m_configureEvents.append({serial, requestedClientSize});
+        m_configureEvents.append({serial, requestedClientSize, rect.topLeft()});
     } else {
+        m_acknowledgedConfigureEvent.reset();
         updateGeometry(rect);
-        return;
     }
-
-    // The surface position is updated synchronously.
-    RectF updateRect = m_frameGeometry;
-    updateRect.moveTopLeft(rect.topLeft());
-    updateGeometry(updateRect);
 }

 void LayerShellV1Window::doSetNextTargetScale()
@@ -284,6 +282,7 @@ void LayerShellV1Window::handleConfigureAcknowledged(quint32 serial)
     while (!m_configureEvents.isEmpty()) {
         const LayerShellV1ConfigureEvent head = m_configureEvents.takeFirst();
         if (head.serial == serial) {
+            m_acknowledgedConfigureEvent = head;
             break;
         }
     }
@@ -304,6 +303,10 @@ void LayerShellV1Window::handleCommitted()
     if (surface()->buffer()) {
         markAsMapped();
     }
+    if (m_acknowledgedConfigureEvent && m_acknowledgedConfigureEvent->size == clientSize()) {
+        updateGeometry(RectF(m_acknowledgedConfigureEvent->position, m_frameGeometry.size()));
+        m_acknowledgedConfigureEvent.reset();
+    }
 }

 void LayerShellV1Window::handleAcceptsFocusChanged()
diff --git a/src/layershellv1window.h b/src/layershellv1window.h
index 9f7a6e1d64..7dc205ab97 100644
--- a/src/layershellv1window.h
+++ b/src/layershellv1window.h
@@ -15,6 +15,7 @@ struct LayerShellV1ConfigureEvent
 {
     quint32 serial;
     QSizeF size;
+    QPointF position;
 };

 class AutoHideScreenEdgeV1Interface;
@@ -78,6 +79,7 @@ private:
     bool m_screenEdgeActive = false;
     WindowType m_windowType;
     QList<LayerShellV1ConfigureEvent> m_configureEvents;
+    std::optional<LayerShellV1ConfigureEvent> m_acknowledgedConfigureEvent;
     QTimer m_rescalingTimer;
 };

